  sellerSetupNotCompleted: { en:'Seller Setup Not Completed', fr:'Configuration vendeur non terminée', pt:'Configuração do vendedor não concluída', ar:'إعداد البائع غير مكتمل', sw:'Usanidi wa Muuzaji Haujakamilika', zh:'卖家设置未完成', hi:'विक्रेता सेटअप पूरा नहीं हुआ', id:'Pengaturan Penjual Belum Selesai', bn:'বিক্রেতা সেটআপ সম্পূর্ণ হয়নি', ur:'بائع سیٹ اپ مکمل نہیں', ja:'出品者設定が未完了です', ko:'판매자 설정이 완료되지 않음' },
  sellerSetupNotCompletedDesc: { en:'Complete your seller profile to start listing items and reaching customers.', fr:'Complétez votre profil vendeur pour commencer à publier des articles et toucher des clients.', pt:'Conclua seu perfil de vendedor para começar a anunciar itens e alcançar clientes.', ar:'أكمل ملف البائع الخاص بك لبدء إدراج العناصر والوصول إلى العملاء.', sw:'Kamilisha wasifu wako wa muuzaji ili kuanza kuorodhesha bidhaa na kufikia wateja.', zh:'完善您的卖家资料，即可开始发布商品并触达客户。', hi:'आइटम लिस्ट करना और ग्राहकों तक पहुँचना शुरू करने के लिए अपनी विक्रेता प्रोफ़ाइल पूरी करें।', id:'Lengkapi profil penjual Anda untuk mulai memasang item dan menjangkau pelanggan.', bn:'আইটেম তালিকাভুক্ত করা এবং গ্রাহকদের কাছে পৌঁছানো শুরু করতে আপনার বিক্রেতা প্রোফাইল সম্পূর্ণ করুন।', ur:'اشیاء درج کرنا اور صارفین تک پہنچنا شروع کرنے کے لیے اپنا بائع پروفائل مکمل کریں۔', ja:'商品の出品と顧客へのリーチを始めるには、出品者プロフィールを完成させてください。', ko:'상품 등록과 고객 도달을 시작하려면 판매자 프로필을 완성하세요.' },
  completeSellerSetup: { en:'Complete Seller Setup', fr:'Terminer la configuration vendeur', pt:'Concluir configuração do vendedor', ar:'إكمال إعداد البائع', sw:'Kamilisha Usanidi wa Muuzaji', zh:'完成卖家设置', hi:'विक्रेता सेटअप पूरा करें', id:'Selesaikan Pengaturan Penjual', bn:'বিক্রেতা সেটআপ সম্পূর্ণ করুন', ur:'بائع سیٹ اپ مکمل کریں', ja:'出品者設定を完了', ko:'판매자 설정 완료' },
