/** Translate a main category title by its data/categories.ts id; falls back to the English title from the data file. */
export function trCategory(id: string, fallbackTitle: string, lang: string): string {
  const map = CATEGORY_T[id];
  if (!map) return fallbackTitle;
  return t(map, lang) || fallbackTitle;
}

/** Shorthand alias for translate — use tr('key', lang) in page components */
export const tr = translate;

export function getDir(lang: string): 'ltr' | 'rtl' {
  return RTL_LANGS.has(lang) ? 'rtl' : 'ltr';
}
